import { createCredential } from '@nexusid/sd-jwt/issuer';
import type { SDJWTCredential, RawClaim } from '@nexusid/types';
import type { HECDegreeData } from './hec-client';
import fs from 'fs';
import path from 'path';

function loadIssuerPrivateKey(): string {
  // 1. Prefer env var (for Docker / CI environments)
  if (process.env.HEC_ISSUER_PRIVATE_KEY) {
    return process.env.HEC_ISSUER_PRIVATE_KEY.replace(/\\n/g, '\n');
  }

  // 2. Fall back to key file generated by scripts/generate-issuer-keys.ts
  const keyPath = path.resolve(__dirname, '../../.keys/issuer-private-key.pem');
  if (fs.existsSync(keyPath)) {
    return fs.readFileSync(keyPath, 'utf8');
  }

  throw new Error(
    'HEC issuer private key not found. ' +
    'Set HEC_ISSUER_PRIVATE_KEY env var or run scripts/generate-issuer-keys.ts first.',
  );
}

export class CredentialBuildError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'CredentialBuildError';
  }
}

export async function buildCredential(
  hecData: HECDegreeData,
  userPublicKey: string,
): Promise<SDJWTCredential> {
  let privateKey: string;
  try {
    privateKey = loadIssuerPrivateKey();
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : String(err);
    throw new CredentialBuildError(`Failed to load HEC issuer private key: ${msg}`);
  }

  // Always-visible claims — safe to expose in every presentation
  const alwaysVisibleClaims: Record<string, unknown> = {
    credential_type: 'education',
    issuer_name: 'Higher Education Commission Pakistan',
    verified: true,
    // cnf (confirmation) binds this credential to the holder's public key
    cnf: {
      jwk: userPublicKey,
    },
  };

  // Selectively disclosable fields — holder chooses which to reveal
  const selectiveFields: RawClaim[] = [
    { field: 'student_name',        value: hecData.student_name },
    { field: 'degree_title',        value: hecData.degree_title },
    { field: 'university',          value: hecData.university },
    { field: 'registration_number', value: hecData.registration_number },
    { field: 'year_of_award',       value: hecData.year_of_award },
  ];

  try {
    const credential = await createCredential({
      claims: selectiveFields,
      alwaysVisibleClaims,
      issuerDID: 'hec.gov.pk',
      subject: hecData.registration_number,
      issuerPrivateKey: privateKey,
      keyId: 'hec-issuer-key-v1',
      expiresInDays: 365 * 5, // HEC degrees are valid for 5 years before re-verification
    });

    return credential;
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : String(err);
    throw new CredentialBuildError(`Failed to build HEC SD-JWT credential: ${msg}`);
  }
}
